import { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import projectService from "@/services/projectService";
import clientService from "@/services/clientService";

export default function CreateProjectModal({ isOpen, onClose, onSuccess }) {
  const [formData, setFormData] = useState({
    project_name: "",
    description: "",
    client_id: "",
    project_type: "audit",
    start_date: "",
    estimated_end_date: "",
    budget: "",
  });

  const [clients, setClients] = useState([]);
  const [loading, setLoading] = useState(false);

  // Obtener clientes
  useEffect(() => {
    const fetchClients = async () => {
      try {
        const response = await clientService.getAll();
        setClients(response);
      } catch (error) {
        console.error("Error al cargar clientes:", error);
      }
    };
    if (isOpen) fetchClients();
  }, [isOpen]);

  // Manejar cambios en los inputs
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  // Enviar formulario
  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      await projectService.create({
        ...formData,
        budget: parseFloat(formData.budget),
      });

      alert("✅ Proyecto creado exitosamente");

      // Limpiar formulario
      setFormData({
        project_name: "",
        description: "",
        client_id: "",
        project_type: "audit",
        start_date: "",
        estimated_end_date: "",
        budget: "",
      });

      // Refrescar lista y cerrar modal con pequeño delay
      onSuccess();
      setTimeout(() => onClose(), 100);
    } catch (error) {
      alert(error.response?.data?.detail || "❌ Error al crear el proyecto");
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="sm:max-w-[600px]">
        <DialogHeader>
          <DialogTitle>Crear Nuevo Proyecto</DialogTitle>
          <DialogDescription>
            Llena los campos para registrar un nuevo proyecto.
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4 mt-4">
          {/* Nombre */}
          <div>
            <Label>Nombre del Proyecto</Label>
            <Input
              name="project_name"
              value={formData.project_name}
              onChange={handleChange}
              required
            />
          </div>

          {/* Descripción */}
          <div>
            <Label>Descripción</Label>
            <Input
              name="description"
              value={formData.description}
              onChange={handleChange}
            />
          </div>

          {/* Cliente */}
          <div>
            <Label>Cliente</Label>
            <select
              name="client_id"
              value={formData.client_id}
              onChange={handleChange}
              required
              className="w-full border rounded-md p-2"
            >
              <option value="">Seleccione un cliente</option>
              {clients.map((client) => (
                <option key={client.id} value={client.id}>
                  {client.client_name}
                </option>
              ))}
            </select>
          </div>

          {/* Tipo de proyecto */}
          <div>
            <Label>Tipo de Proyecto</Label>
            <select
              name="project_type"
              value={formData.project_type}
              onChange={handleChange}
              className="w-full border rounded-md p-2"
            >
              <option value="audit">Auditoría</option>
              <option value="consulting">Consultoría</option>
              <option value="implementation">Implementación</option>
            </select>
          </div>

          {/* Fechas */}
          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label>Fecha de Inicio</Label>
              <Input
                type="date"
                name="start_date"
                value={formData.start_date}
                onChange={handleChange}
                required
              />
            </div>
            <div>
              <Label>Fecha Estimada de Fin</Label>
              <Input
                type="date"
                name="estimated_end_date"
                value={formData.estimated_end_date}
                onChange={handleChange}
              />
            </div>
          </div>

          {/* Presupuesto */}
          <div>
            <Label>Presupuesto (USD)</Label>
            <Input
              type="number"
              name="budget"
              value={formData.budget}
              onChange={handleChange}
              min="0"
              step="0.01"
              required
            />
          </div>

          {/* Botones */}
          <div className="flex justify-end gap-2 pt-4">
            <Button
              type="button"
              variant="outline"
              onClick={() => setTimeout(() => onClose(), 50)}
            >
              Cancelar
            </Button>
            <Button type="submit" disabled={loading}>
              {loading ? "Guardando..." : "Guardar Proyecto"}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}
